-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[9147] = { id = 9147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Courier", description = "What are you standing around for?  Can't you see this boy needs immediate attention?  By the looks of it, the plague is beginning to take over his body.  Within minutes not even a master apothecary like me will be able to save him.\n\nThe animals south of the river all carry the plague in their blood.  Go across the bridge and hunt the plagued beasts there.  Bring me enough plagued blood samples and I'll distill a serum capable of saving this blood elf.  Hurry!", progress = "Well?  Did you bring me what I need?  Hurry, or the pretty {race} boy is a goner!", completion = "Just in time, {name}!  I was about ready to start digging a hole for our friend here.\n\nMy potion seems to be working; he's coming to.\n\nHey, I think he's trying to get your attention.  Why don't you talk to him?", objectives = "Apothecary Thedra in Eversong Woods wants you to bring her 4 Plagued Blood Samples from beasts in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9148] = { id = 9148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Tranquillien", description = "I... I'm too weak to continue.  I carry a dire warning from Regent Lord Theron, in the form of a letter.  You'll have to deliver it for me.\n\nTake it to Arcanist Vandril in Tranquillien.  You'll find the town further to the south along this road.  Go there and... find Vandril...", progress = "You have the letter?", completion = "Finally!  We've waited for a response from the regent lord for weeks! Let me see here...\n\n<Vandril begins to read the letter.>\n\nWhat's this? A dark presence? He senses a dark presence in the Ghostlands?! No kidding; I could have told him that!\n\nThis is what we've been waiting for?", objectives = "Bring the Letter from Silvermoon to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9149] = { id = 9149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plagued Coast", description = "To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies.\n\nI've come here to study the murlocs since, like us, they've retained free will in undeath.  What makes these lowly mongrels so special?  I need to find out, {name}!\n\nTravel northwest and bring me their spines so that I may study the accumulation of plague in their marrow.  Who knows what secrets their little bones hold?", progress = "Have you obtained the specimens I asked of you, {name}?", completion = "Excellent!  These spines will be invaluable to my research!  When I find a cure for the plague and word of my name spreads I'll make sure to make mention of you!\n\nIn the meantime, take these as a reward.  You might need them if you decide to go back to the coast.", objectives = "Bring 6 Plagued Murloc Spines to Apothecary Renzithen in Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9150] = { id = 9150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Past", description = "Can you believe it?  We have an actual functioning arcane sanctum up and running southeast of here: the Sanctum of the Sun.  All manner of important magisters have come to take part in running it.\n\nOf course they've all forgotten about the Sanctum of the Moon.  Not much remains of it and its energies have given rise to bizarre creatures.\n\nI'm not one to let good resources go to waste, however.  Go to the Sanctum of the Moon and see if you can recover the crystallized essences from the creatures there.", progress = "Did you obtain the essences, {name}?", completion = "These are remarkably powerful, {name}.  I'm very pleased with your work.", objectives = "Magister Darenis wants you to travel to the Sanctum of the Moon to the west of Tranquillien and recover 8 Crystallized Mana Essences from the Arcane Devourers and Mana Shifters that inhabit the structure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9151] = { id = 9151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum of the Sun", description = "You've proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge.  Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy's doorstep.\n\nThey've rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area.  They plan to launch an offensive into Deatholme, Dar'Khan's stronghold.  You would do well to join them, {name}.  I'm sure they can make use of a seasoned {class} like yourself.", completion = "Darenis sent you?  Very well, I suppose we can use your aid in fighting Dar'Khan's forces.", objectives = "Speak to Magister Idonis in the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9152] = { id = 9152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomber's Supplies", description = "How am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of ghouls!\n\nWant to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the Dead Scar is a fork in the road. The hill that my cart had to be left on lies just beyond.", progress = "Just as soon as I get the rest of my supplies, I'll be open for business. The forces here aren't going to get very far if they can't purchase what they need to ply their trades.\n\nWar zones can be such profitable places, wouldn't you agree, {class}? Now, did you manage to fight your way to my cart through all of those ghouls?", completion = "With the rest of my supplies here, I can finally open shop. I'm sure that the high executor will be most pleased to hear that the war on Dar'Khan and the Scourge can commence.\n\nAnd, of course, there's the small matter of your recompense. Very well, {class}, here is the coin that I alluded to. Do be sure to drop by should you find yourself in need of any trade goods.", objectives = "Retrieve Rathis Tomber's Supplies and return it to him at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9153] = { id = 9153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Shadow", description = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.\n\nOnly through our combined efforts will they be repelled.\n\nEach necropolis is supported by nearby magical circles, and among each circle swarms a host of undead creartures. We have determined that destroying these mindless hordes will destroy the circle's defenses.You will be able to choose one of these rewards:", objectives = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9154] = { id = 9154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Hope Chapel", description = "The Scourge have returned in greater numbers than we have seen before.  This must be the doing of the Lich King!  The Argent Dawn is recruiting all willing and capable men and women to defend our lands.\n\nIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectives = "Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9155] = { id = 9155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Dead Scar", description = "If you've made it this far then you probably know about the Dead Scar and how to this day mindless Scourge follow the path of destruction that Arthas created on his way to Silvermoon City.\n\nMake yourself useful and thin down the Scourge's numbers in the Scar.  If you prove to be worth your salt I'll put in a good word for you.", completion = "Not bad, {name}.  Keep it up, we could use a few more people like you around here.", objectives = "Slay 10 Risen Hungerers and 10 Gangled Cannibals on the Dead Scar. Return to Deathstalker Rathiel in Tranquillien for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9156] = { id = 9156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Knucklerot and Luzran", description = "A bounty is hereby declared for the abominations known as Knucklerot and Luzran.  These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats.  Individuals seeking to claim the reward must present the abominations' heads to Deathstalker Rathiel as proof of the deed.", progress = "You have something to show me, {name}?", completion = "Ah... Luzran and Knucklerot!  Not looking so tough anymore, are you?  I can see you're still looking ugly as ever.\n\nTake one of these rewards, {name}.  You've earned it.", objectives = "Search the Ghostlands for Knucklerot and Luzran. Bring their heads to Deathstalker Rathiel in Tranquillien for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9157] = { id = 9157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Rituals", description = "Every year we, the denizens of Suncrown Village, would take part in a ritual to keep the different aspects of nature under our control.  Dominion over the element of water was symbolized by the summoning and enslavement of an elemental named Aquantion.  Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us instead!\n\nWe wore medallions shaped like waves during the ritual.  Seek them at the bottom of the lake; we'll need them to free my compatriots' spirits!", progress = "Have you obtained the medallions, {name}?  The drowned still haunt this lake!", completion = "With these necklaces we shall once again summon Aquantion.  The rebellious elemental will pay and our deaths will be avenged!", objectives = "Bring 8 Wavefront Medallions to Geranis Whitemorn in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9158] = { id = 9158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearers of the Plague", description = "You show courage coming to the Ghostlands, {name}.  There is much work to be done here and not enough brave souls to do it.\n\nI've a thankless task to offer you, should you have the inclination to aid our cause.  The very wildlife in this land has been tainted by the plague and we must stop it from spreading.  Hunt the ghostclaw lynxes to the east and south of here and return when you've slain enough of them.", completion = "You've done well, {name}.  It's important that the plague doesn't spread to the healthy wildlife in Eversong.  I have more work for you if you're looking for something to do.", objectives = "Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 10 Ghostclaw Lynxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9159] = { id = 9159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curbing the Plague", description = "You've proven your worth as an ally, {name}.  I need you to continue your task and track down more plagued wildlife.  This time seek out some of the more dangerous beasts.  Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here.  Return to me when you're done.", progress = "Have you completed the task I asked of you, {name}?", completion = "You've taken your task seriously and thus I'd like to present you with suitable rewards.  We need more allies with your courage and determination, {name}.", objectives = "Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 8 Spindleweb Lurkers and 10 Vampiric Mistbats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9160] = { id = 9160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate An'daroth", description = "{class}, we are having difficulty with a group of night elves that have recently taken over a nearby island. They've set up a small camp at the old high elf ley-line nexus, An'daroth, to the northwest. There is a dirt path that leads up to it just past the Dead Scar.\n\nI suggest that you lend us your aid by going there, investigating what they are up to, and slaying as many of the conceited night elves as you can.", completion = "Disappointing that the night elves' plans were not readily apparent at An'daroth. However, those objects that looked like small magically-grown trees with powered orbs atop them sound interesting. It would appear that we'll need to be more direct in our information gathering efforts.\n\nHere, take this coin and these potions. I believe that you'll have use for them before we're done dealing with these night elves.", objectives = "Investigate the area at An'daroth, kill 12 Sentinel Spies and then return to Dame Auriferous at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9161] = { id = 9161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor's Shadow", description = "Dar'Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands.  Dar'Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf.  Much of his time was spent inside Dawnstar Spire, northeast of here.  He hid there for many nights, scheming against his own. \n\nSearch the tower for more information, {name}.  Perhaps he had a journal or kept notes.  One never knows where useful information might present itself.", completion = "After browsing through the first few pages of this old book, you come to the conclusion that it once belonged to the one known as Dar'Khan Drathir.", objectives = "Travel to Dawnstar Spire in the Ghostlands and search for any clues involving Dar'Khan's past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9162] = { id = 9162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints of the Past", description = "As you skim through the pages in the journal you're overcome by an unnerving sense of being watched.\n\nThe contents are unsettling.  Dar'Khan's soul was one filled with hatred and contempt for his own people.  The extent of his machinations and plots are all documented in great detail.\n\nPerhaps there is something here that Vynna will find useful.", progress = "Tell me, {name}, what did you find out?", completion = "This information is very valuable, {name}.  We all knew about Dar'Khan's plans to steal the power of the Sunwell for the Scourge, but much of the information found here is completely new to us.  Magister Kaendris at the Sanctum of the Sun will want to look at this.", objectives = "Return to Ranger Vynna at the Farstrider Enclave with Dar'Khan's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9163] = { id = 9163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Occupied Territory", description = "Now, the more direct course of action that we are going to take, to figure out what these night elves are really up to, is to have you go to their island and steal any information that you can come by.\n\nI want you to head west down the road out of town to Shalandis Isle, just off the coast. Go there and recover any plans they might have on the island or on their ship.", progress = "How fare our efforts to uncover the night elf plot on Shalandis Isle, {class}?", completion = "Troubling! These plans show the night elf forces at An'daroth, which we already knew, but also at An'owyn, a more remote ley-line nexus to the southeast.\n\nThere is a third nexus to the east, which is not mentioned, named An'telas. I have a very bad feeling about all of this, {class}.", objectives = "Steal the Night Elf Plans: An'daroth, Night Elf Plans: An'owyn and Night Elf Plans: Scrying on the Sin'dorei, and return them to Dame Auriferous at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9164] = { id = 9164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captives at Deatholme", description = "Ah, yes. I possess a draught that will break most forms of alchemically induced stupor.\n\nSide effects include confusion, nausea and - in rare cases - temporary blindness. All much preferable to whatever the Scourge plans to do to those prisoners in Deatholme, if you ask me.\n\nBest of luck, brave {class}. You are going to need it.", completion = "Excellent job, {name}.  Without your help those prisoners would've lost their minds and souls to the Scourge.", objectives = "Take Janeda's Restorative Draught to Deatholme and rescue Apprentice Varnis, Apothecary Enith and Ranger Vedoran. Return to Arcanist Janeda at the Sanctum of the Sun for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9165] = { id = 9165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writ of Safe Passage", description = "Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here.\n\n<Guard Didier wipes his brow.>\n\nNow we need to wait here for Field Marshal Chambers to arrive. He'll sign your writ of safe passage to take back to Dispatch Commander Metz at Light's Hope Chapel.\n\nAnd {name}, watch what you say around Chambers. He's the 'bite off your head and spit down your wind pipe' type of guy - except that he'll actually do it...", progress = "Name, rank and serial number!", completion = "<Dispatch Commander Metz takes the writ and signs it.>\n\nExcellent work, {name}. Outstanding even! Take this as a token of our appreciation. No pun intended, scrub.", objectives = "Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9166] = { id = 9166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Plans to An'telas", description = "You must deliver the recovered night elf plans to An'telas for me. It is to the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum of the Sun.\n\nMagister Sylastor is there conducting ongoing studies into the ley-line nexus energy for potential use in our fight against the Scourge. Have him look at these plans to shed some light on what it is that these night elves are up to.", progress = "Oh, thank goodness for you!", completion = "It was just horrible! Night elves! They conjured their moon crystal here for some nefarious plot, but I snuck away and gathered a larger group of our scouts and casters from the nearby Sanctum of the Sun. We killed most of them and the rest of the group is hunting down the remnants!\n\nI'm glad that you're here now; I was only left a couple of scouts for protection! It's not safe out here!\n\nGive me a moment and I'll read through these plans to see what the night elves are up to.", objectives = "Deliver the Night Elf Plans to Magister Sylastor at An'telas in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9167] = { id = 9167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor's Destruction", description = "Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours.  The Scourge have maintained their chokehold on the region for far too long.\n\nThe time has come for payback, {name}.  Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours.\n\nHe who sought to steal the power of the Sunwell must die.  Go to Deatholme, the Scourge stronghold south of the Dead Scar.  Bring me Dar'Khan's head and your deeds will go down in history!", progress = "Is it done, then?  Has Dar'Khan been destroyed?", completion = "Today you've dealt a deadly blow to the Scourge's grasp in the region.\n\nWith the vile traitor gone, it shall not be long before we've reclaimed our lands and our greatness is restored once again.", objectives = "Slay Dar'Khan Drathir inside Deatholme and bring his head to Magister Kaendris at the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9168] = { id = 9168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Deatholme", description = "Deep inside Deatholme our enemies are striving to create stronger, deadlier spectral soldiers.  These abhorrent creatures are perfect killing machines, handcrafted by Dar'Khan himself and hardened by the dark magic of Deatholme.\n\nTravel to the Tower of the Damned inside Deatholme and destroy them, {name}.  We cannot let our enemy's army grow in power while we struggle to maintain our foothold in the Ghostlands.", objectives = "Destroy 8 Eyes of Dar'Khan and report back to Magister Idonis at the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9169] = { id = 9169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deactivate An'owyn", description = "Their moon crystals are scrying devices -- they're going to spy on us! I know that An'daroth can't provide enough power for that, but An'owyn, directly to the south, most definitely can!\n\nFrom the plans I now have a basic knowledge of how these moon crystals work; enough to shut them down. They're keyed so that they can be turned off. You must go to An'owyn, retrieve the controlling orb from one of the night elves and then use it on the moon crystal to stop them from enacting their plan!\n\nHurry, {class}!", progress = "Is it over then, {class}? Did you deactivate the night elf moon crystal at An'owyn?", completion = "That's a relief, {class}! I can assure you that if you hadn't deactivated those scrying orbs we would be in a more tenuous position than the one we're already in! To think, surrounded by enemies, and one of them able to spy upon our every move!\n\nBut now we don't need to worry about that thanks to you! Here, take this, I want you to be rewarded for your efforts and I just happen to have a few things here that I no longer have any use for.\n\nThank you again, {name}!", objectives = "Retrieve the Crystal Controlling Orb and then use it to deactivate the Night Elf Moon Crystal at An'owyn. Then return to Magister Sylastor at An'telas in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9170] = { id = 9170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dar'Khan's Lieutenants", description = "The odious traitor, Dar'Khan, has risen to great power among the ranks of the Scourge.  His lieutenants command vast armies of undead against our dwindling numbers.\n\nMasophet the Black, Jurion the Deceiver, Borgoth the Bloodletter, Mirdoran the Fallen.  Learn these names well for in the Ghostlands these Scourge leaders are second only to Dar'Khan himself.  Slay them and their mindless armies will be thrown into disarray.", completion = "Dar'Khan's armies will soon fall.  The Scourge shall not stand a chance against the combined might of the sin'dorei and the Forsaken.", objectives = "Magister Idonis wants you to venture into Deatholme to slay Masophet the Black, Jurion the Deceiver, Borgoth the Bloodletter and Mirdoran the Fallen. Report back to him in the Sanctum of the Sun in the Ghostlands after you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9171] = { id = 9171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culinary Crunch", description = "This is intolerable!  I have nothing to work with here! Milady asks me to come from Silvermoon City; she deserves cuisine as befits her station.  No?  But I get here and there is no food.  You must go out, {class}, and bring back fresh kills so that I have something to prepare.\n\nDame Auriferous prefers a crunchy texture to her food.  There are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar.  Disgusting, I know, but that's what we have to work with.", progress = "I believe I can hear the dame's belly rumbling even from here!  I take it that you are here talking to me because you have what I asked you to obtain?", completion = "Very well, these will have to do.  No, don't describe them crawling around, I don't want to know!  I'll work my magic upon these legs and they'll turn out quite tasty.  A little spice here, a pinch of herb there, and then of course some arcane ingredients, and voila, a meal fit for a queen... or in this case, a dame.\n\nYour service has been adequate, {class}.  Here, take this recipe and some samples.", objectives = "Collect 5 Crunchy Spider Legs and return them to Master Chef Mouldier at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9172] = { id = 9172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Magister Kaendris", description = "The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge's weaknesses with the aid of the Forsaken.  Magister Kaendris will know what to do with this information.\n\nYou'll find the Sanctum of the Sun southwest of here.  You must hurry, {name}.  Dar'Khan is a cunning enemy and watches our every move!", progress = "You wish to speak to me?", completion = "This book... it can't be!  It's Dar'Khan's very own handwriting.  There must be information here that will reveal a weakness in our opponent.\n\nYou've done well in coming to us, {name}.  The Farstriders have shown great wisdom in leaving this matter in our hands.  This armor should help you further our cause.", objectives = "Bring Dar'Khan's Journal to Magister Kaendris at the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9173] = { id = 9173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking Windrunner Spire", description = "{class}, I want you to reclaim Windrunner Spire!\n\nIt's an honor, really. Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken and former ranger-general of the elves. But now it's been overrun by the mindless Scourge.\n\nTo get there take the road south until it branches. Take the right fork and after crossing the Dead Scar continue southwest. You can't miss it.", completion = "I'm certain that Lady Sylvanas will be pleased to hear that we've made progress in the matter.\n\nHere, take this coin as payment for your efforts.", objectives = "Slay 8 Deatholme Acolytes and 10 Fallen Rangers, and return to High Executor Mavren at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9174] = { id = 9174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquishing Aquantion", description = "That willful elemental ended many lives that fateful day when he revolted against us.  By calling to the lowly murloc to sabotage our rites he subverted our magic and turned it against us.\n\nShow him our thirst for vengeance has not waned!  Take these medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake.  Aquantion shall immediately answer your summons!\n\nBeware, {race}!  Without our magic controlling him, his wrath will be unrestrained.  Destroy Aquantion so we may rest!", progress = "Has Aquantion been destroyed yet?", completion = "You've avenged our deaths and broken Aquantion's grasp on our souls.  We may finally rest.", objectives = "Geranis Whitemorn wants you to swim to the bottom of the lake east of Suncrown Village and use the Bundle of Medallions on the Altar of Tidal Mastery. Summon and slay the elemental known as Aquantion and return to Geranis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9175] = { id = 9175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lady's Necklace", description = "The necklace shimmers, a remarkable piece of jewelry that doesn't seem to succumb to the gloom that permeates the Ghostlands. Given the inscription, and where you found it, it must be the lost property of Lady Sylvanas Windrunner herself!\n\nPerhaps it would be best to first take it to High Executor Mavren at Tranquillien? He seems to be the highest ranking Forsaken in the area and is sure to know what to do with it.", progress = "What's that you have there, {name}?", completion = "You say that you found it on one of the Scourge at Windrunner Spire and that there's an inscription on it? Let me see!\n\nHere, take this coin for a job well done.", objectives = "Take The Lady's Necklace to High Executor Mavren at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9176] = { id = 9176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twin Ziggurats", description = "According to this journal, Dar'Khan promised the Scourge two powerful elven artifacts: the stone of light and the stone of flame.  These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge.\n\nThe crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat now stand, in the middle of the Dead Scar.  If they're still held there, we need to recover them.  Their power will be greatly useful in our struggle against the enemy.", progress = "Have you recovered the crystals yet?", completion = "The rumors were true!  The stone of light and the stone of flame do exist!  We shall use their power to create weapons against Dar'Khan.\n\nUse them when the time is right and the energies of the Sunwell, trapped within these objects, will vanquish him with the very power he sought to steal from us!", objectives = "Travel to the Bleeding Ziggurat and the Howling Ziggurat and recover the Stone of Light and the Stone of Flame. Return to Magister Kaendris at the Sanctum of the Sun after recovering the items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9177] = { id = 9177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Undercity", description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.", progress = "And you are?\n\nWhat's that you have there? That necklace looks somehow familiar. Give it here!", completion = "<Sylvanas takes the necklace from your grasp.>\n\nIt can't be! After all this time, I thought it was lost forever.\n\n<After a lingering moment the Lady seems to become aware once again of her surroundings, composing herself.>\n\nYou thought this would amuse me? Do you think I long for a time before I was the queen of the Forsaken? Like you, it means nothing to me, and Alleria Windrunner is a long dead memory!\n\n<She drops the amulet to the ground.>\n\nYou may now remove yourself from my presence, {class}.", objectives = "Take The Lady's Necklace to Lady Sylvanas Windrunner at the Royal Quarter in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9178] = { id = 9178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Dense Weightstone", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-091:\n\n120 Dense Weightstones.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 120 Dense Weightstones and the Craftsman's Writ - Dense Weightstone - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9179] = { id = 9179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Imperial Plate Chest", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-428:\n\n3 Imperial Plate Chests.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", progress = "Filling a work order, {class}?", completion = "More armor for the troops! Fantastic, {name}!", objectives = "Deliver 3 Imperial Plate Chests and the Craftsman's Writ - Imperial Plate Chest - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9180] = { id = 9180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Undercity", description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.", progress = "And you are?\n\nWhat's that you have there? That necklace looks somehow familiar. Give it here!", completion = "<Sylvanas takes the necklace from your grasp.>\n\nIt can't be! After all this time, I thought it was lost forever.\n\n<After a lingering moment the Lady seems to become aware once again of her surroundings, composing herself.>\n\nYou thought this would amuse me? Do you think I long for a time before I was the queen of the Forsaken? Like you, it means nothing to me, and Alleria Windrunner is a long dead memory!\n\n<She drops the amulet to the ground.>\n\nYou may now remove yourself from my presence, {class}.", objectives = "Take The Lady's Necklace to Lady Sylvanas Windrunner at the Royal Quarter in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9181] = { id = 9181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Volcanic Hammer", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-697:\n\n3 Volcanic Hammers.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 3 Volcanic Hammers and the Craftsman's Writ - Volcanic Hammer - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9182] = { id = 9182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Huge Thorium Battleaxe", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-6020:\n\n3 Huge Thorium Battleaxes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 3 Huge Thorium Battleaxes and the Craftsman's Writ - Huge Thorium Battleaxe - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9183] = { id = 9183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Radiant Circlet", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-80:\n\n3 Radiant Circlets.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 3 Radiant Circlets and the Craftsman's Writ - Radiant Circlet - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9184] = { id = 9184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Wicked Leather Headband", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-971:\n\n10 Wicked Leather Headbands.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 10 Wicked Leather Headbands and the Craftsman's Writ - Wicked Leather Headband - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9185] = { id = 9185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Rugged Armor Kit", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-448:\n\n25 Rugged Armor Kits.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", progress = "Filling a work order, {class}?", completion = "The rugged armor kits have many uses, {name}. They aren't JUST for slapping on certain armor pieces for added protection. Like this one here, I'm going to use it as teapot cozy.", objectives = "Deliver 25 Rugged Armor Kits and the Craftsman's Writ - Rugged Armor Kit - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9186] = { id = 9186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Wicked Leather Belt", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-736:\n\n9 Wicked Leather Belts.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 9 Wicked Leather Belts and the Craftsman's Writ - Wicked Leather Belt - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9187] = { id = 9187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Runic Leather Pants", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-8485:\n\n4 Runic Leather Pants.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 4 Runic Leather Pants and the Craftsman's Writ - Runic Leather Pants - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9188] = { id = 9188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Brightcloth Pants", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-95:\n\n6 Brightcloth Pants.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 6 Brightcloth Pants and the Craftsman's Writ - Brightcloth Pants - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9189] = { id = 9189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to the Sepulcher", description = "You have stirred the lady's heart, though it no longer beats.\n\nHowever, I have instructions that must be delivered to the Sepulcher in Silverpine Forest.  Advisor Sorrelon represents us to the Forsaken there.\n\nThe shortest route, barring the use of their flying bats, is to leave Undercity and take the road south.  Follow the signposts.  Finding the place shouldn't be difficult.  Brace yourself, though; the Sepulcher itself is a dilapidated crypt.\n\nThese Forsaken are certainly odd creatures.", progress = "Greetings, brother. What news do you bring?", completion = "I see here that Ambassador Sunsorrow has high hopes for your continued rise as a credit to the sin'dorei. Unfortunate that business with Lady Sylvanas, though. Pay it no heed, {name}, you did the right thing in returning her necklace. She should have been grateful, but such is the way of royalty.\n\nWhile you are here, should you choose to assist with the tasks of the Forsaken, be on your best behavior. You wouldn't want to damage our new bond with the Horde now would you?", objectives = "Deliver the Sealed Sin'dorei Orders to Advisor Sorrelon at the Sepulcher in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9190] = { id = 9190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Runecloth Boots", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-635:\n\n8 Runecloth Boots.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 8 Runecloth Boots and the Craftsman's Writ - Runecloth Boots - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9191] = { id = 9191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Runecloth Bag", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-9999:\n\n8 Runecloth Bags.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 8 Runecloth Bags and the Craftsman's Writ - Runecloth Bag - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9192] = { id = 9192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Underlight Mines", description = "The Underlight Mines to the southwest have been overrun by a clan of gnolls calling themselves the Blackpaw. I don't need to remind you how important those mines are to us as a strategic asset in our ongoing campaign here in the Ghostlands!\n\nTake the south road out of town and follow the fork to the right. Just past the ziggurat on the right there will be a short dirt path to the west. Follow it.\n\nThe ore must flow!", completion = "That's a fair job of butchery you managed there, {class}. We'll get the miners back to work now. I'm sure they'll be disappointed that their break is over, but there's armor and weaponry to be made, and that requires ore to be mined.\n\nHere, take this as payment for doing your duty. Go get your armor and weapons repaired, and have a drink on me.", objectives = "Slay 8 Blackpaw Gnolls, 6 Blackpaw Scavengers and 4 Blackpaw Shaman, and return to Deathstalker Maltendis at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9193] = { id = 9193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Amani Catacombs", description = "{class}, our sources tell us that the trolls buried in the Amani Catacombs inside Sungraze Peak have been rising from the dead. I need you to investigate these catacombs and put to the torch any of the unanimated remains you come across so as to prevent any more of these creatures from rising.\n\nThe fastest way there is to head northwest out of the enclave. This will put you near the western entrance to the catacombs.", progress = "This is a most grim and undignified business, {class}. I trust that you will complete this task to milady's complete satisfaction?", completion = "Disgusting, but necessary I can assure you. You have done us good service by investigating this matter, {class}. Please, take this as a token of our generosity and appreciation.", objectives = "Investigate the Amani Catacombs and burn 10 Mummified Troll Remains, then return to Ranger Vynna at Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
