quests[9206] = { id = 9206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ - Lightning Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-9:\n\n30 Lightning Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 30 Lightning Eel and the Craftsman's Writ - Lightning Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9207] = { id = 9207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underlight Ore Samples", description = "I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, {class}?\n\nYou can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.", progress = "How may I help you, {class}?", completion = "My apprentice was unable to take care of this herself?  I shall have a word with her when she returns then, gnolls or not.  Speaking of which, why didn't she return with you?\n\n<The magister sighs.>\n\nThat one is a handful, and is going to be quite a challenge to properly train.  Thank you, {class}, for bringing these samples to me.  We are hoping that we can uncover some special property from them that will help in the fight against the Scourge.\n\nPlease take this coin as a token of my appreciation.", objectives = "Collect 6 Underlight Ore and deliver them to Magister Quallestis at the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9208] = { id = 9208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Protection", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9209] = { id = 9209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Rapidity", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9210] = { id = 9210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Guard - Arcanum of Focus", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9211] = { id = 9211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ice Guard", description = "Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.\n\nAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9212] = { id = 9212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from the Catacombs", description = "These trolls ambushed me and have been keeping me in this cage.  I think they're planning to sacrifice me!  Help me get out of here!\n\nThe lock on the cage isn't that complex... I just can't get to it from this side.  Please escort me back to the Farstrider Enclave.  I'm sure Captain Helios will reward you, and you'll have my undying gratitude!", progress = "You're the one that rescued my ranger?", completion = "You're quite the hero, {class}, to get her out of there alive.  I suppose we'll have to mount an offensive to clear out those catacombs too.  As if we didn't have enough trouble with the living trolls!\n\nYou've done a great thing today, I should reward you.  Take your pick from any of these.", objectives = "Escort Ranger Lilatha to Captain Helios at Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9213] = { id = 9213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Guard", description = "A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.\n\n<Mataus holds his hand out and rubs his fingers together.>\n\nInterested?", progress = "<Mataus yawns.>\n\nBe gone, insect, lest you have something for me.", completion = "<Mataus stuffs the gold into his robe.>\n\nWhat are you still standing around for, {race}? Our business is done.", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9214] = { id = 9214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowpine Weaponry", description = "{class}, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge.\n\nHit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.", progress = "Have those weapons yet? With the Shadowpine numbers decimated we'll finally be able to turn our attention to the fight against the Scourge.", completion = "I'll immediately send a few rangers out to survey the damage that you wreaked upon the Shadowpine trolls. I've no doubt that we'll be able to mop up after your offensive and launch an attack on the Scourge soon if these weapons are any indication of your success.\n\nHere, I want you to take this coin in payment. It's burning a hole in my pouch anyway.", objectives = "Collect 3 Headhunter Axes, 3 Shadowcaster Maces, 3 Catlord Claws and 3 Hexxer Staves. Return them to Captain Helios at Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9215] = { id = 9215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Kel'gash's Head!", description = "WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa.\n\n\n\nREWARD: Yes, but no advances!", progress = "What is that awful smell?", completion = "Ah, Kel'gash's head is what smelled so bad. That's a nice piece of work there, {class}!\n\nWith their chieftain dead, the Shadowpine trolls should be in total disarray. Combined with your recent efforts to decimate their numbers, this should be the perfect opportunity to launch our counter-offensive against them and wipe them out for good.\n\nYou have my thanks, {name}. Might I interest you in one of these?", objectives = "Return the Head of Kel'gash the Wicked to Captain Helios at the Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9216] = { id = 9216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotting Hearts", description = "I hear the Amani trolls eat their enemies' hearts to steal their strength.  They might just be on to something, {name}.  With the proper treatment, the hearts of the unliving can produce potent elixirs.\n\nHunt down the zombies that roam the Dead Scar and bring me their hearts.  I'll show you the kind of enhancement we can perform to your physical prowess against the undead.", progress = "Do you have the zombie hearts I requested, {name}?", completion = "Take this draught, {name}.  After you drink it, your physical strength against the Scourge will receive a boost. If you need more than this sample bring me more hearts.", objectives = "Bring back 10 Rotting Hearts to Magistrix Aminel in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9217] = { id = 9217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Rotting Hearts", progress = "You've brought more ghoul hearts?  I can use as many as you can collect, {name}.", completion = "This will provide you with greater power against the Scourge.   Bring more hearts if you find them, {name}." }
quests[9218] = { id = 9218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinal Dust", description = "The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine.  I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead.\n\nBring me some spinal dust and I'll be glad to provide you with a sample.  You'll find an ample number of skeletons wandering the Dead Scar, west of here.", progress = "Do you have the samples I requested, {name}?", completion = "Take this, {name}.  You'll feel the difference immediately!\n\nFeel free to bring more spinal dust; I can use as much of it as you can provide.  Side effects?  You might start feeling your joints acting up a bit.  Nothing permanent, I assure you!", objectives = "Bring back 10 Spinal Dusts to Magistrix Aminel in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9219] = { id = 9219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Spinal Dust", progress = "You've procured more spinal dust?  I can use as much of it as you bring me.", completion = "This dust is as potent as ever, {name}.  Keep bringing it to me if you're in need to boost your magical powers against the Scourge." }
quests[9220] = { id = 9220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on Deatholme", description = "If you seek to aid our cause there is no better place to start than here and no better time to do it than now.\n\nBy rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme.\n\nGo forth and fight the hordes of undead that inhabit the vile Scourge fortress.", completion = "The Scourge has felt our wrath, {name}.  It won't be long before their cursed citadel lies in ruins.\n\nWith their numbers weakened, it is time to launch an attack on more strategic targets.", objectives = "Slay 5 Eyes of Dar'khan, 6 Nerubis Centurions and 6 Wailers in Deatholme and return to Magister Idonis at the Sanctum of the Sun in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9221] = { id = 9221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9222] = { id = 9222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", objectives = "For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9223] = { id = 9223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9224] = { id = 9224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", objectives = "For 75 Insignias of the Dawn and 75 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9225] = { id = 9225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9226] = { id = 9226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", objectives = "For 7 Insignias of the Dawn and 7 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9227] = { id = 9227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you.", objectives = "For 6 Insignias of the Dawn and 6 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9228] = { id = 9228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epic Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.You will be able to choose one of these rewards:", objectives = "For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9229] = { id = 9229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Ramaladni", description = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.\n\nUnderstand this, {name}, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.\n\nEnter Naxxramas and find what became of Ramaladni.", objectives = "Enter Naxxramas and uncover the Fate of Ramaladni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9230] = { id = 9230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladni's Icy Grasp", description = "Fixing this band may prove to be quite challenging, {name}. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9231] = { id = 9231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9232] = { id = 9232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Song I Know...", description = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9233] = { id = 9233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omarion's Handbook", description = "Wilhelm,\n\nIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.\n\nAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a crook.\n\nIn Disdain,\n\nOmarion", objectives = "Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9234] = { id = 9234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Gauntlets", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets. All you need to do is bring me the materials and pay a small crafting fee.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water and 200 gold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9235] = { id = 9235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers. All you need to do is bring me the materials and pay a small crafting fee.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water and 200 gold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9236] = { id = 9236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icebane Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate. All you need to do is bring me the materials and pay a small crafting fee.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water and 300 gold. You will also need to be of Exalted reputation with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
