quests[9246] = { id = 9246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icy Scale Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 24 Heavy Scorpid Scale, 7 Essence of Water, 5 Cured Rugged Hides and 300 gold. You must also be of Exalted reputation with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9247] = { id = 9247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keeper's Call", description = "{name},\n\nIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.\n\n{name}, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.You will be able to choose one of these rewards:", objectives = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9248] = { id = 9248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Offering", description = "Ishnu-alah, {race}. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.", progress = "Fandu-dath-belore? Oh, pardon me, {name}. I did not recognize you. Have you the scepter?", completion = "Ande'thoras-ethil. It means; 'May your troubles be diminished,' in my native tongue.\n\nWear the band proudly and in good health, {name}.", objectives = "Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9249] = { id = 9249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "40 Tickets - Schematic: Steam Tonk Controller", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
quests[9250] = { id = 9250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frame of Atiesh", description = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.\n\nFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.", objectives = "Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9251] = { id = 9251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, the Befouled Greatstaff", description = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, {name}. I only do as I must.\n\nKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.\n\nAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.\n\nShould you succeed in recovering the pieces, return them to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9252] = { id = 9252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Fairbreeze Village", description = "We've experienced a marked increase in Scourge attacks, {name}.  Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City.  Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.", completion = "Many thanks, {name}.  Our job is a thankless one, but today you helped make it a bit easier.", objectives = "Slay 4 Rotlimb Marauders and 4 Darkwraiths and return to Ranger Sareyn at Fairbreeze Village in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9253] = { id = 9253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runewarden Deryan", description = "This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands.\n\nWe used these ancient stones to protect us against the undead.  Most of them were destroyed or lost after the attack on the Sunwell. \n\nFollow the road south, towards the Ghostlands, and look to the west for a small path.  You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.", completion = "You must've been sent by someone at Fairbreeze Village.  I knew it would just be a matter of time until help arrived.", objectives = "Speak to Runewarden Deryan in Eversong Woods, near the border with the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9254] = { id = 9254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Apprentice", description = "Thank you for your help, {name}.  While I get things back in order here, I'd like to ask you for a favor.  One of my former apprentices embarked in a very dangerous line of research.  She journeyed to the East Sanctum, in the middle of the Dead Scar.\n\nI worry for her well-being.  See if you can find her and convince her to return to her senses.", completion = "It's so nice of my old mentor to check on me.  It's too bad she lost faith in my research long ago.\n\nDon't waste your time trying to get me to return to her; you can either help me with my research or leave.", objectives = "Speak to Apprentice Mirveda at the East Sanctum in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9255] = { id = 9255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Notes", description = "As discouraging as my research results are, they still contain valuable data.  I must have a magister review my work before it is taken seriously.  Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.", progress = "You've something for me?", completion = "These notes... are shocking.  If they're correct it means the damage to the land on the Dead Scar is irreversible.\n\nI'll notify the grand magister right away.  More reason for our race to escape this world and find our true fate in Outland.", objectives = "Deliver the Research Notes to Magistrix Landra Dawnstrider at Fairbreeze Village in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9256] = { id = 9256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fairbreeze Village", description = "I have another task for you, {name}.  Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard.  He has requested reinforcements which we cannot yet provide.  Seek him out and grant him whatever aid you can.\n\nFairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south.  Good luck, {name}.", completion = "Thanks for coming, {name}.  Things are worse than we had anticipated.  The Wretched have taken over Sunsail Anchorage in its entirety.", objectives = "Speak to Ranger Degolien at Fairbreeze Village in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9257] = { id = 9257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9258] = { id = 9258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scorched Grove", description = "A foul taint in the soil precedes the expansion of the Scourge into a new area.  The protective runestones along the border with the Ghostlands have warded the land against this taint in the past.\n\nThe westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading.\n\nMy sister, Larianna Riverwind, watches over the Scorched Grove.  Go find her; she might have some work for you.", completion = "Ah, my brother sent you.  I do have a task I could use assistance with.", objectives = "Find Larianna Riverwind near the Scorched Grove in the southwest of Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9259] = { id = 9259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor to the Bloodsail", progress = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", completion = "Let us observe a minute of silence for our fallen mates, {name}.\n\n<The Bloodsail Traitor grins at you and winks.>\n\nBeing a traitor is one thing, murdering yer own buckos... that'd be just downright despicable, aye!" }
quests[9260] = { id = 9260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Stormwind", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9261] = { id = 9261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Ironforge", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Ironforge from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Ironforge and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9262] = { id = 9262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Darnassus", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Darnassus from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Darnassus and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9263] = { id = 9263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Orgrimmar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Orgrimmar from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Orgrimmar and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9264] = { id = 9264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Thunder Bluff", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Thunder Bluff from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Thunder Bluff and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9265] = { id = 9265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of the Undercity", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles near their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9266] = { id = 9266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Amends", progress = "You must've done something really bad to us or our friends, {name}. At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, {name}. You're on a quick path to redeeming yourself with our fair town." }
quests[9267] = { id = 9267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Old Wounds", progress = "You'd better think twice before setting foot in Ratchet, {name}!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", completion = "I'm happy you're seeing the error of your ways, {name}.  Keep the supplies coming; we're not going to forget about you so easily!" }
quests[9268] = { id = 9268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War at Sea", progress = "You seek to befriend the goblins of Tanaris once again, {name}?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", completion = "Keep it coming, {name}.  Us goblins don't forget that easily!" }
quests[9269] = { id = 9269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9270] = { id = 9270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9271] = { id = 9271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9272] = { id = 9272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing the Part", objectives = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard!  Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben.  Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9273] = { id = 9273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Prize Voucher" }
quests[9274] = { id = 9274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Drowned", description = "The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, {name}.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.\n\nThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.\n\nIf you're up to the task, I want you to go to the lake and put an end to their suffering, {name}.  You will have my gratitude as well as theirs... I'm sure.", completion = "I appreciate your help, {name}.  It pains me to see the spirits of my ancestors in their pitiful state.  May they finally get the rest they deserve.", objectives = "Ranger Krenn'an, at the Farstrider Enclave in the Ghostlands, wants you to kill 8 Vengeful Apparitions and 8 Ravening Apparitions in the nearby lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9275] = { id = 9275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Dash of Seasoning", description = "I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem.\n\nAt my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining!\n\nCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.", progress = "Isn't this exciting? I really do take great pride in my work; I hope you appreciate it, {class}.\n\nSo, I trust that you have 'seasoned' the food at the troll camps in Zeb'Nowa?", completion = "Ah, excellent! I knew that a {race}-delivery system would make for the most efficient application of the poison. With any luck the Shadowpine trolls will get fat on it before keeling over. That should get them off of the backs of the Farstriders, and me back to Tranquillien.\n\nIt has been a pleasure working with you, {class}!", objectives = "Poison the Troll foodstuff at the camps in Zeb'Nowa and then return to Apothecary Venustus at the Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9276] = { id = 9276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Zeb'Tela", description = "Our resources are spread pretty thin here, {class}, so your help is going to be invaluable.  The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out.\n\nUntil then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased.\n\nThink you could head east to Zeb'Tela and hurt them a little?", completion = "Good, good! You handled that very well! Let's see if you're up to something a little more difficult now.", objectives = "Kill 8 Shadowpine Shadowcasters and 8 Shadowpine Headhunters, and return to Farstrider Solanna at Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9277] = { id = 9277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Zeb'Nowa", description = "Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal.\n\nWhat do you say, {name}? Ready to deal with some more trolls?", completion = "Unbelievable! You really should talk to the captain about joining up as a Farstrider.\n\nAlright, {name}, you've given us the breathing room that we need to continue building up our forces here. Actually, by your account there aren't many of those trolls left at all! Maybe now we can join with Tranquillien and attack Deatholme?\n\nI think you've earned a little something. Take your pick.", objectives = "Kill 10 Shadowpine Catlords and 10 Shadowpine Hexxers, and return to Farstrider Solanna at the Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9278] = { id = 9278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Jaeleil in Azure Watch.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", objectives = "Bring the Azure Watch Gift Voucher to Jaeleil in Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9279] = { id = 9279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Survived!", description = "Nevermind my injuries, <brother/sister>. It's a miracle that any of us are alive!\n\nIt didn't look like you'd pull through; you've been in suspension for weeks.\n\nSomething happened and the Exodar crashed. Many have died.\n\nBut I'm relieved that you are alive, {name}. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.", completion = "{name}, by my eternal soul, it is good to see you!  I don't know why the Exodar crashed.  Only those of us that were in this part of the ship remain.\n\nThere's not much time if we're to save everyone that we can!", objectives = "Speak with Proenitus at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9280] = { id = 9280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Healing Crystals", description = "Our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but they are mostly concentrated in the northwest.", progress = "{name}, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the {race} way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.", objectives = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and give them to Proenitus at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9281] = { id = 9281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Magister Kaendris sent me down here to clear the area of any hostile wildlife.  Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge.\n\nNow if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life!\n\nIf you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.", completion = "Thanks for giving me a hand, {name}.  I was dreading the thought of venturing into the woods this close to Deatholme.", objectives = "Apprentice Vor'el at Andilien Estate in the Ghostlands wants you to slay 10 Greater Spindlewebs and 10 Ghostclaw Ravagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9282] = { id = 9282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farstrider Enclave", description = "Magisters and Farstriders may not see eye to eye all the time, {name}.  When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions.\n\nRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.", completion = "Kaendris sent you?  I might have a task for you, {class}.", objectives = "Magister Kaendris, at the Sanctum of the Sun, wants you to talk to Ranger Vynna at the Farstrider Enclave in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9283] = { id = 9283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Survivors!", description = "The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.\n\nYou'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.\n\nThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.\n\nYou must save them, {name}.", progress = "We'll survive this yet with your help.", completion = "The Light be praised! You've done what only a true hero could have done, {name}! The {race} you saved owes their continued life to your selflessness!\n\nPlease, take this supply pouch. You look like you can use it more than I.", objectives = "Use your Gift of the Naaru ability on one of the Draenei Survivors spread throughout Ammen Vale, then return to Zalduun at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9284] = { id = 9284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aldor Faction Test" }
quests[9285] = { id = 9285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consortium Faction Test" }
quests[9286] = { id = 9286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scryers Faction Test" }
quests[9287] = { id = 9287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paladin Training", sourceObjective = "I am heartened by your initiative to speak with me.  In the past I was responsible for the training of young paladins as they entered our order.  This is a duty and privilege that I humbly take up once more.  Your name has been mentioned as one who seeks to do good in the name of the Light.  It would be my honor to guide you in your first steps as a {class}.\n\nShall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9288] = { id = 9288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter Training", sourceObjective = "I'm glad that you have come to me.  For quite some time now I have been responsible for the training of our young hunters, a responsibility that I intend to continue on this new world.  I've had my eye upon you for a while now and it would be my honor to help train you in the ways of the {class}.\n\nShall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9289] = { id = 9289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warrior Training", sourceObjective = "It is good that you seek my guidance.  For centuries I have taught young {race} warriors, so I may know a thing or two on how you should begin.  I see in you the makings of a great {class}, but only if you listen carefully to what I have to teach.\n\nAre you ready to learn, young {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9290] = { id = 9290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Training", objectives = "I am pleased that you have come seeking my knowledge. We have much to do if your magical skills are to be honed.\n\nFor over a hundred years I have taught the arcane, frost and fire magics, and I can feel them just as strongly on this world.  Would you like me to impart some of what I know to you?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9291] = { id = 9291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priest Training", objectives = "It gives me great hope for our future that you come seeking my wisdom.  While I have my hands full here with our injured, I am not so busy that I cannot spare a moment to aid you in your first steps as a {class}.  To walk in the Light is the highest of callings, and one that I am certain you are more than ready to undertake!\n\nSpeak with me again when you feel that you are ready to begin your training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.You will be able to choose one of these rewards:", objectives = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9293] = { id = 9293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Must Be Done...", description = "The nearby lake has been contaminated by one of the ship's power crystals.  Many of the plants and animals of Ammen Vale have been mutated because of this.\n\nI have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis.  They can be found to the west in the Ammen Fields.\n\nWill you help me, {class}?", progress = "I'll need all of the samples in good condition if we're to have a chance of cleansing the lake.\n\nWe don't have much time, {class}!", completion = "These will do. Thank you, {class}!\n\nWhile you were out, I managed to gather some equipment together to make an analysis of the samples.  This should only take a moment.", objectives = "Gather 10 Lasher Samples and return them to Botanist Taerix at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9294] = { id = 9294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing the Lake", description = "Thank goodness, I think it'll work!  I have an agent for you to spread at Silverline Lake to the south.  It will neutralize the effects of the irradiated ship's power crystal that fell there.\n\nSwim out and scatter the neutralizing agent near it.  Don't worry, you won't be exposed long enough to become irradiated.", progress = "The sooner you disperse the agent at the lake, the fewer native creatures that will be mutated by drinking the water, including ourselves!\n\nI'm sorry that we can't do anything to help the poor creatures that have already been infected.  If only my lab equipment were intact.", completion = "From what you describe, the neutralizing agent worked! I just wish that I knew how long it will last; we really need to remove that power crystal from the lake entirely.\n\nThank you, {name}! I will tell Tedon to try the neutralizing agent on one of the captured beasts at once.", objectives = "Disperse the Neutralizing Agent at the Irradiated Power Crystal, then return to Botanist Taerix at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9297] = { id = 9297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
