quests[9299] = { id = 9299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Careworn Note to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9300] = { id = 9300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Page from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Ragged Page to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9301] = { id = 9301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envelope from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Bloodstained Envelope to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Crumpled Missive to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9303] = { id = 9303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", progress = "The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", completion = "With many of the owlkin now inoculated, we can focus on getting out of here and not have to worry about wiping out the owlkin population in the area.\n\nHere, choose from these.  You've done good work, and you deserve to be rewarded!", objectives = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9305] = { id = 9305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", progress = "When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", completion = "Let me take a look at those.\n\nYes, I think that these will do nicely; good job, {name}. The emitter is rather complex so it may take some time to finish the repairs. I'll let you know when it's ready.\n\nIn the meantime, you might see if Vindicator Aldar has anything he could use you for.", objectives = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9309] = { id = 9309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scout", description = "We now have several separate confirmations of unusual activity up on the Shadow Ridge.\n\nThis is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet.\n\n{class}, I need you to head southwest to the other side of Silverline Lake and find Tolaan, and see what has delayed him.", completion = "Help... blood elves!  They... ambushed... me.  Don't have... long.", objectives = "Find and speak with Tolaan at Shadow Ridge in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal faintly radiating necrotic energy.You will be able to choose one of these rewards:", objectives = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9311] = { id = 9311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Elf Spy", description = "I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed.\n\nThen Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.", completion = "I thank you for dealing with the blood elf surveyor.  Surely she was their leader.  Rest assured, we will deal with whatever remnant of them is still nearby.\n\nPlease, take one of these weapons as a sign of my gratitude.", objectives = "Slay Surveyor Candress and then inform Vindicator Aldar at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9312] = { id = 9312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emitter", description = "{name}, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.", completion = "I got it, I got it!  I think I managed to fix the emitter!  Here, I'll just activate this last crystal and that should do it.\n\nTake a look at the emitter, {name}.  It looks like it's beginning to work... someone is appearing!", objectives = "Speak with Technician Zhanaa at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9313] = { id = 9313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Azure Watch", description = "By all that is good, {name}, you must go at once to this Azure Watch and speak with Dyvuun!\n\nThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.\n\nSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.\n\nThank you, we wouldn't have made it without you!", completion = "Ah, good to see you again!  I'm glad that we were both able to get our emitters fixed or we might never have found one another.  And don't worry, we'll see to it that Ammen Vale gets help and supplies.\n\nSpeaking of assistance, now that you're here, go around and introduce yourself to the others.  I know that there's plenty to do.", objectives = "Speak with Technician Dyvuun at Azure Watch on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9314] = { id = 9314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word from Azure Watch", description = "{class}! A couple mutated beasts jumped me and my leg is injured.\n\nI was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch.\n\nBe sure to ask her for a place for yourself to stay in.", completion = "Oh, you must be one of the survivors we've been hearing about!\n\nI'm glad that you came. Don't worry, we will send someone to see to Aeun's injured leg.\n\nI'm most interested in hearing all about your harrowing story of survival. You're a brave one to have made it all the way here.", objectives = "Speak with Caregiver Chellan at Azure Watch on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9315] = { id = 9315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anok'suten", description = "Come closer, I am ... dying.\n\nI was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader.\n\n<The dying blood elf coughs up a good amount of blood.>\n\nYou must find and ... slay Anok'suten.  Get help.  She wanders around ... Suncrown Village.", completion = "I apologize for the shoddy intelligence, {class}.  Had I known of this Anok'suten ahead of time, I surely would have told you.\n\nWe're spread too thin and things are slipping through the cracks!", objectives = "Slay Anok'suten and return to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones" }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil" }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Mana Potion" }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Healing Potion" }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", objectives = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", objectives = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "What's this? Unless I'm mistaken, this flame has been taken from the heart of Orgrimmar itself! The fierce hearts of the orcs and trolls are reflected in its searing heat. What a fine addition to our collection--how brave you are, stealing into the enemy's lair to retrieve the sacred flame!\n\nI wonder what power lurks in the other cities...", objectives = "Return the Flame of Orgrimmar to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "Unless I miss my guess, this fire has been taken from the cliffs of Thunder Bluff! How it sings with the power of the spirits! You are quite the thief, {name}. Take this as just payment for your skill. Now, if only we had the flames of all four cities...", objectives = "Return the Flame of Thunder Bluff to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all four cities, who knows what we could accomplish?", objectives = "Return the Flame of the Undercity to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9327] = { id = 9327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken", description = "I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren. He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", completion = "I know that we Forsaken appear monstrous to your eyes, but I assure you we mean your people no harm. We are here because of a common enemy: Dar'Khan the traitor! He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nOur leader, Lady Sylvanas Windrunner, originally hails from these lands, and in fact used to be an elf. She has a history with Dar'Khan and wants him dead as much as your people do.\n\nWe will defeat him together, {class}!", objectives = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9328] = { id = 9328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Sin'dorei", description = "This is the beginning of a new chapter in the history of our race, {name}.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", progress = "You seek audience with me, {class}?  I do not recall hearing of an appointment.", completion = "Now that's one face I was not expecting to see so soon.\n\nThis is quite the good news, {name}, in more ways than you can imagine.", objectives = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9329] = { id = 9329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken", description = "I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren.  He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", completion = "We Forsaken are here because of a common enemy with the blood elves: Dar'Khan!  He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nLady Sylvanas Windrunner, who originally hails from these lands, and used to be an elf, has a history with Dar'Khan and wants him dead!\n\nWe will defeat him, {class}, and you will help us do it!", objectives = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "And this brightly-burning fire... you say it came from Stormwind? Remarkable! That must have been quite an adventure! I'll pay you for this, of course. If you find anything else like this, be sure to speak with me again.", objectives = "Return the Flame of Stormwind to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "This hearty flame must be from the halls of Ironforge; it's as stalwart as the dwarves themselves. A fine catch, {name}. If I had the fires of the other cities... ah, but never mind. Here is your payment.", objectives = "Return the Flame of Ironforge to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire aches of ancient sorrow, {name}. You pulled this from the roots of Teldrassil, you say? Fascinating! Here is a reward for your skill. Return to me should you find anything else like this; I may have a use for it.", objectives = "Return the Flame of Darnassus to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Gloves" }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil" }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones" }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Healing Potion" }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Mana Potion" }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to Cenarion Circle", progress = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", completion = "You honor us, {name}.  With your continued efforts we will overcome all obstacles." }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", objectives = "You've proven yourself, today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9340] = { id = 9340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Fissure", description = "We're dangerously close to becoming fenced in by Alliance forces.  With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes.\n\nI've given it some thought and have arrived at a solution.  We're to establish a secret path through the Great Fissure.\n\nYes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us.  I want you to go and kill a good number of them.  They shall learn fear.", completion = "Good job, {name}.  That should teach the rock flayers to stay far away from us.", objectives = "Ranger Captain Venn'ren at Falcon Watch wants you to slay 8 Stonescythe Whelps and 3 Stonescythe Alphas at the Great Fissure, east of Falcon Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn" }
quests[9342] = { id = 9342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauding Crust Bursters", description = "As if the gan'arg that overran the mines aren't bad enough, now we've got gigantic worms encroaching on us from the other direction!\n\nWith Thrallmar's garrison pinned down defending against the Legion and tending to their wounded, it leaves me and the miners to deal with the problems.\n\n<The foreman gestures at the sleeping peons.>\n\nAnd you can see how useful they are...\n\nI'd gladly pay you their wages to clear out some of those worms.", objectives = "Foreman Razelcraz at the mines near Thrallmar wants you to kill 15 Marauding Crust Bursters. The worms have a tendency to attack suddenly from their tunnels below ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn" }
quests[9344] = { id = 9344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hasty Departure", description = "Greetings, {name}. Outland is a perilous place, as many of our expedition quickly learned. I'm afraid young Grelag may have learned that lesson firsthand.\n\nGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.\n\nHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.", sourceObjective = "Far Seer Regulkut wants you to track down her student Grelag.", sourceObjectiveStatus = "unverified-source-field" }
quests[9345] = { id = 9345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Salve", description = "Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me!\n\nI managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here.\nNow, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.", progress = "Have you brought the plants?", completion = "These should do the job. I'm going to prepare the salve and finish my splint before making my way back to Thrallmar. Why do I have the feeling that I know what Far Seer Regulkut will say when she sees me?\n\n<Grelag sighs half-heartedly.>\n\nThank you for your help, {name}. I have some of the spineleaf left over. You're welcome to take it with you. Who can tell when it will prove useful?", objectives = "Gather 12 Hellfire Spineleaf plants for a salve and return to Grelag at Spinebreaker Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9346] = { id = 9346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Helboars Fly", description = "Have you ever seen a helboar fly? They don't even need wings!\n\n<Watch Commander Krunk laughs.>\n\nThe fight against the Legion camps to the north has depleted our supplies, including catapult ammunition. This is the perfect opportunity to try something new.\n\nInstead of using boulders, I want to try igniting the corpses of the starving helboars I've seen around the eastern ruins and use them to bombard the Legion's camps.\n\nAre you going to volunteer, or do I have to order you?", objectives = "Watch Commander Krunk in Thrallmar wants you to bring him 10 Plump Helboar Carcasses from Starving Helboars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9347] = { id = 9347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidwalkers Gone Wild", description = "Examining the essence reveals violent swirls of energy sealed within a vessel made of unidentifiable material. As you consider it, you can feel it beginning to tug at your mind, inviting you to come closer and to look deeper.\n\nFeeling your will begin to slip away, you break your gaze immediately. Its presence remains at the edge of your consciousness as you determine what to do with it.", objectives = "Bring the Pulsating Voidwalker Essence to Mahuram Stouthoof in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9348] = { id = 9348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravager Roundup", description = "Outland is rife with fascinating creatures. Fascinating -- and extremely dangerous.\n\nThe area is rich with predators, which seems strange for such a barren land, but a closer look reveals something of a hierarchy.\n\nThe rock flayers seem to have domesticated another predator, the ravager, and breed them as hunting companions and guard animals. I need to know more about how they're training these ravagers. We must shut down and examine their breeding site to the southwest, near the Terokkar Forest.", objectives = "Slay 10 Captive Ravager Hatchlings and retrieve 12 Ravager Eggs for Mahuram Stouthoof in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9349] = { id = 9349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravager Egg Roundup", description = "I'm starving!\n\nThere's irony in that, wouldn't you say?  A starving cook?\n\n<Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.>\n\nAccording to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest.  It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!\n\nI could cook up quite a feast if only someone were brave enough to go down there and get me some!", progress = "You have those eggs yet?\n\n<Legassi's stomach grumbles in anticipation.>", completion = "In order to have great cuisine, you need to have great ingredients.  And these eggs look great!\n\nI've just finished cleaning off my frying pan, so you're more than welcome to join me for a meal!", objectives = "Retrieve 12 Ravager Eggs for Legassi at the Zeppelin Crash in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9350] = { id = 9350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Peon's Work is Never Done", description = "The Legion's constant assaults take a heavy toll on our defenses. If the palisade falls, so will Thrallmar. I've assigned peons to reinforce and repair the walls, but we're running out of materials.\n\nGrelag, one of the Far Seer's students, is well versed in the old ways and suggested returning to an ancient practice. Long ago, the clefthoof hunt supplied us with meat, hides, and bones. Taking up the hunt again, with the clefthoof to the southeast, would provide what's needed and honor the ancestors.", objectives = "Gather 8 Clefthoof Hides and 8 sets of Clefthoof Bones from the Raging Clefthoof. Return to Watch Commander Krunk in Thrallmar once you have all the materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9351] = { id = 9351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidwalkers Gone Wild", description = "Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here!\n\nTo the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries.\n\nIf you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!", progress = "Were you able to get the essence?", completion = "This is perfect! In fact, I think it's going to work so well, I might just have to redesign the engine to take advantage of all this extra power. If, I mean, when we get out of here, I'll have to show my design to everyone back at Area 52!", objectives = "Bring 10 Condensed Voidwalker Essences to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9352] = { id = 9352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassian Intrusions", description = "Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings.\n\nThough most reports are unfounded, one recent incident demands further investigation.  The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant.\n\nTravel there and deal with anyone that looks suspicious.  Report back to Ley-Keeper Velania, who watches over the sanctum.", completion = "Night elves?  Here?  Those rats!\n\nDo you suppose they had anything to do with the malfunction in my sanctum?  If you have any information, you'd better take it to Captain Sunbrand at once!", objectives = "Travel to the West Sanctum, southwest of Falconwing Square and defeat any intruders present there. Report your findings to Ley-Keeper Velania.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Gift Box Voucher" }
quests[9354] = { id = 9354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for New Materials", description = "<The dwarf looks up from his work expectantly.>\n\nIf you're looking to commission a piece, get in line, {class}. I've got my hands full maintaining the Sons' equipment and preparing us for the day when we'll take the battle to the enemy again.\n\nOur metal stocks are getting very low since crust borers invaded the mines. I've been experimenting with natural materials from the raging clefthoof that graze in the areas northeast of the Hold, and while they're no substitute for iron, I'm learning to make do.", objectives = "Gather 8 Clefthoof Hides and 8 Clefthoof Sinews from the Raging Clefthoof. When you have the materials, bring them to Humphry in Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9355] = { id = 9355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job for an Intelligent Man", description = "Well met, {class}. Now that reinforcements are finally arriving, we can recapture some semblance of a normal life.\n\nOne of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area.\n\nIf you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.", progress = "Were you able to clear the road?", completion = "Well done, {name}. We shouldn't be too quick to congratulate ourselves, though. I'm certain we haven't seen the last of those worms. If they show their hideous heads around these parts again, the Sons'll be ready for them!", objectives = "Kill 15 Marauding Crust Bursters and return to Foreman Biggums at Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9356] = { id = 9356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smooth as Butter", description = "Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it!\n\nTake a look at the wreckage over there. He calls it a \"rough\" landing.\n\nSure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often!\n\nI think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.", progress = "I can't wait to see the look on his face when he digs in. Ever since the crash, he's been complaining that all I can think of is food. Well, someone's got to feed us while he tinkers with the zeppelin!", completion = "Ravager Eggs.  Bam!\n\nHellboar Bacon. Bam!\n\nBuzzard Wings. Bam!  Bam!\n\nWhat a great meal.  You've really got to try it.", objectives = "Bring 12 Plump Buzzard Wings to Legassi at the Zeppelin Crash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9357] = { id = 9357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Aeldon Sunbrand", description = "If you're looking for work, you'll find Captain Sunbrand inside the Inner Elf Gate, through the doors behind me.\n\nNow leave me be, I must question this scoundrel.", sourceObjective = "Report to Aeldon Sunbrand at the Inner Elf Gate in Eversong Woods.", sourceObjectiveStatus = "unverified-source-field" }
quests[9358] = { id = 9358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranger Sareyn", description = "Don't take the safety of this village for granted.  We're under siege by the Scourge on the east and the Wretched to the west.\n\nRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar.  Follow the road eastwards out of town and see if you can lend her a hand.", completion = "You're here to help us?  Why didn't you say so earlier?  We can always use a hand!", objectives = "Report to Ranger Sareyn outside Fairbreeze Village in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9359] = { id = 9359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farstrider Retreat", description = "Your help in subduing the Wretched has been invaluable.  The Farstriders would surely have use for someone like you in their fight against the Amani trolls.\n\nLook for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.", completion = "You're here to help?  Excellent!\n\nThe battle against the Amani trolls has taken its toll on us and capable fighters such as yourself are always welcome.", objectives = "Report to Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9360] = { id = 9360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Invasion", description = "Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village.\n\nYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.", progress = "What do you want to show me?", completion = "The trolls have been keeping us pinned here while planning an attack on Fairbreeze Village.  We were not expecting this at all.", objectives = "Deliver the Amani Invasion Plans to Lieutenant Dawnrunner at Farstrider Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9361] = { id = 9361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helboar, the Other White Meat", description = "Those eggs are superb, but what do you say we kick it up another notch?\n\nA side of bacon would round out the meal perfectly and I know just where to get it.\n\nThis place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck!\n\n<Legassi rummages around in his pack and produces a flask.>\n\nThis wasn't made for use on pork, but cooking is as much about improvisation as anything else!", progress = "Were you successful in purifying the helboar meat?", completion = "Hmm...\n\nThis looks edible, if spiced properly. Just don't tell Screed where his breakfast came from, ok?", objectives = "Legassi at the Zeppelin Crash wants you to gather 8 Purified Helboar Meat. To purify the meat, use the Purification Mixture on the Tainted Helboar Meat you gather from Helboars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities...", objectives = "Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9363] = { id = 9363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning Fairbreeze Village", description = "Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans.  Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack.  Tell Degolien I will send him reinforcements as soon as possible.", completion = "The information you've brought is of vital importance, {name}.  Now that we know of the trolls' plans we can prepare for an attack.\n\nWe won't be caught with our guard down.", objectives = "Travel to Fairbreeze Village in Eversong Woods and speak to Ranger Degolien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!", objectives = "Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", objectives = "You've proven yourself, today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9366] = { id = 9366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Felblood", description = "Northeast of here lie the Pools of Aggonar.  Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them.\n\nThat blood, though old and diluted, still possesses tremendous power.  Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood.  Slay them and retrieve as much felblood as you can.  I'll make it worth your while.", progress = "The felblood... did you obtain it, {name}?", completion = "The energy contained in these samples is tremendous, {name}.  Now we just need to ensure that our access to this felblood continues uninterrupted.", objectives = "Ryathen the Somber at Falcon Watch in Hellfire Peninsula wants you to bring him 6 Felblood Samples from the Terrorfiends that inhabit the Pools of Aggonar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9369] = { id = 9369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Healing Crystals", description = "We are the draenei.  Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but mostly in the northwest.", progress = "Have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.", objectives = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and bring them to Proenitus at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9370] = { id = 9370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing Must Be Stopped", description = "Our scouts captured a draenei paladin at the Pools of Aggonar.  He was to take part in a cleansing ritual to purify the pools.  We must stop the draenei from succeeding or we will lose our supply of felblood!\n\nHe was carrying this signaling gem, looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety.  Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei.\n\nI suggest that you take a friend or two along.", progress = "You've returned, {name}.  Did you put an end to the draenei's folly?", completion = "That'll show those holy fanatics to mind their own business.", objectives = "Place the Signaling Gem near the Altar of Aggonar at the Pools of Aggonar and defeat any Draenei Anchorites that respond to your summons. Return to Ryathen the Somber at Falcon Watch with the Signaling Gem after completing this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9371] = { id = 9371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanist Taerix", description = "{name}, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.", completion = "Oh, thank goodness you've come.  We have much to do.", objectives = "Speak with Botanist Taerix at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9372] = { id = 9372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Contamination", description = "Welcome to the Cenarion Post, {class}. We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places.\n\nThe Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.", progress = "Were you able to collect the blood samples?", completion = "Well done, {name}. These blood samples will prove helpful in my research and in the Expedition's wider studies of Outland's creatures.\n\nIf I could isolate what causes these creatures to change continuously, perhaps I could concoct an antidote.", objectives = "Thiah Redmane, at the Cenarion Post in Hellfire Peninsula, has asked you to gather 6 Helboar Blood Samples from Hulking Helboars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9373] = { id = 9373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Missive", description = "Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out.\n\nThe only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.", progress = "Good day, {class}. What brings you to my encampment?", completion = "Thank you for bringing this to me, {class}. I was wondering why I hadn't heard from the Expedition in so long. I wonder how long ago this message was dispatched and what befell its carrier.\n\nHere's a bit of coin for your trouble.", objectives = "Return the Eroded Leather Case to Thiah Redmane, camped near the Ruins of Sha'naar in western Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9374] = { id = 9374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelion's Journal", description = "My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland.  He spent much of his time studying slimes, of all things!\n\nHe went missing in there a few days ago.  They say he's dead and there's nothing I can do about it.\n\nOne thing I can do is try to ensure that his research doesn't die with him.  Go northeast to the pools and look for his journal.  He always carried it inside a brown knapsack.", progress = "Any luck, {name}?  You'll find the Pools of Aggonar north of Hellfire Citadel.", completion = "My husband's journal... it's not about research at all!\n\nHow could I've been such a fool?  \"Magical properties of fel-infused slime forms,\" he really had me going there.", objectives = "Magistrix Carinda at Falcon Watch in Hellfire Peninsula wants you to go to the Pools of Aggonar and retrieve Arelion's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9375] = { id = 9375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Falcon Watch", description = "<The battered blood elf's face displays relief at your presence.>\n\nPlease, {class}, get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings.\n\nI was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles.\n\nAs I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!", completion = "<Taleris shouts to several of the blood elves at the outpost.>\n\nGet her inside and see to her wounds!\n\n<Taleris turns back to you.>\n\nShe's fortunate that you found her when you did, {class}. I don't think she'd have lasted much longer out there.\n\nCan you make out what she was saying?", objectives = "Protect the Wounded Blood Elf Pilgrim on her way to Falcon Watch, then speak with Taleris Dawngazer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9376] = { id = 9376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilgrim's Plight", description = "That wounded pilgrim seems to be shouting something about a pack.\n\nWhen you encountered her, did you see a pack nearby? Hmm...\n\nShe must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers.\n\nIf she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life.\n\nGo to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.", progress = "Things aren't going well. At this rate, she'll never make it back onto the road. Were you able to find that pack?", completion = "Thank you for returning this, {name}. I'm not sure what significance it holds for the wounded pilgrim, but she refuses to let anyone get near her until it's in her hands again.", objectives = "The Wounded Blood Elf Pilgrim was attacked by Quillfang Ravagers while camped in Dustquill Ravine. Find her camp and search it for the missing pack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9377] = { id = 9377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thirsting For Power", description = "Falcon Watch serves as a stop for pilgrims on their long journey into Outland. Although we are an early stop on the way, many of the pilgrims reach us exhausted and wracked by their addictions.\n\nIn a world such as this, many find it necessary to relearn mastery of their magical addiction. Food and drink help, {class}, but magical energy is their greatest need. The remains of Outland's voidwalkers provide a potent source of energy, but they grow rare and can only be found in the Warp Fields to the southwest.", objectives = "Retrieve a Potent Voidwalker Essence from the Vengeful Voidwalkers and return to Taleris Dawngazer at Falcon Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9378] = { id = 9378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DND FLAG The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9379] = { id = 9379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortifying the Felhunter", description = "Greetings, {class}. Say hello to Jir'see here, too. Don't worry, he won't bite unless I tell him to.\n\n<Angela makes a cooing sound at the felhunter.>\n\nHe's so tiny in comparison to the warp hounds that live in Outland. But we're going to fix that right up, yes we are, aren't we, Jir'see?\n\nI think I've figured out a way to do it. I'll need plenty of blood from the warp hounds and that's where you come in. While you're hunting them in the southeast, I'll get ready for the experi... err, treatment.", objectives = "Gather 6 Warp Hound Blood and bring them to Angela \"The Claw\" Kestrel in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9380] = { id = 9380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounded for More", description = "I swear, if I get one more letter from Ironforge...\n\nHave you ever tried to explain something to someone who just wouldn't listen, {class}? I sent the boys in Ironforge the warp hound they asked for, and they had the gall to write back saying they wanted a \"pack\" of the things! A pack!\n\nSo, I tried to tell 'em that warp hounds are solitary creatures, but they'd have none of it. I've given up on setting 'em straight. Grab 6 of the best ones from the area east of the hold, and brimg 'em back here?", objectives = "Collect 6 Undamaged Warp Hound Corpses and bring them to Prospector Murantus in Honor Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9381] = { id = 9381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trueflight Arrows", description = "With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time.\n\nI could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.", progress = "Were you able to get all the feathers?", completion = "These should do the job. I was concerned that the rangers might be short on arrows for a while, but that's one less thing I have to worry about. Thank you for your help, {class}.", objectives = "Gather 8 Bonestripper Tail Feathers from Bonestripper Vultures and bring them to Falconer Drenna Riverwind at Falcon Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9382] = { id = 9382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Clefthoof", description = "Greetings, {class}.\n\nI'm certain your travels in Outland have shown you something of the corruption in this world. It is so pervasive that it has transformed the very creatures who dwell here - the ones that survived, that is.\n\nThe clefthoof to the south and west were once docile grazers, but the corruption has created an unquenchable rage in them. They only find release from their torment in death, though it grieves us to spill their blood. Will you help me end the suffering of the bristlehide clefthoof?You will be able to choose one of these rewards:", objectives = "Kill 15 Bristlehide Clefthoof and return to Amaan the Wise at the Temple of Telhamat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9383] = { id = 9383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ambitious Plan", description = "The blood elves epitomize the irresponsible use of magic, {class}. They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics.\n\nI've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.", progress = "Have you used the crystal's magic against an uncontrolled voidwalker?", completion = "You've done well, {name}. It seems the containment crystal is holding for now, but how long it will last remains a mystery. We'll keep an eye on it and prepare more of the crystals in the meantime.", objectives = "Use the Sanctified Crystal against a wounded Uncontrolled Voidwalker and return to Elsaana at the Temple of Telhamat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9385] = { id = 9385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Ravagers", description = "So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot.  Little did we know how close we were to the quillfang ravagers.\n\nThey are relentless predators and have made any sort of work on our part impossible.  There's a bit of coin in it for you if you can deal with them for us.  Do you feel up to it?", completion = "Well done, {name}.  That should teach those beasts who's boss!", objectives = "Kill 10 Quillfang Ravagers and return to Gremni Longbeard in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, {name}.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9387] = { id = 9387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Source of the Corruption", description = "Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light.  What corruption caused their great race to devolve into the Broken and Lost Ones?\n\nI've heard a theory that exposure to fel energies is what caused the mutation.  I would like to put that theory to the test.\n\nNorthwest of here lie the Ruins of Sha'naar.  There you will find lowly Broken commanded by Illidari taskmasters.  Bring me demonic essences from the taskmasters so that I can test them on this draenei.", progress = "Have you obtained the samples?", completion = "You've been most helpful, {name}.  Now let's see what we can learn from our blue friend.", objectives = "Travel to the Ruins of Sha'naar in Hellfire Peninsula and obtain 5 Demonic Essences from the Illidari Taskmasters. Return to Apothecary Azethen at Falcon Watch after you've completed the task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.You will be able to choose one of these rewards:", objectives = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.You will be able to choose one of these rewards:", objectives = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9390] = { id = 9390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Sedai", description = "Hear my plight, {class}.  My brother, Sedai, left long ago to contact the orcs of Mag'har Post.  Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them.\n\nHe's been missing for days and I fear for the worst.\n\nWould you set my mind to rest and look for him?  Sedai must be somewhere nearby to the east.", completion = "You've found the body of a young draenei paladin.  He appears to have been slain by a blow to his back.", objectives = "Anchorite Obadei wants you to look for his brother, Sedai, nearby to the east in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9391] = { id = 9391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Path", description = "With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims.  Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east.\n\nLight the three beacons and return to me.  Be warned that the beacons will attract any nearby rock flayers when you first light them.", progress = "Have you done what I asked of you, {name}?", completion = "The Great Fissure, though still dangerous, will prove to be a useful path for our pilgrims.\n\nWith the Alliance watching all the roads in and out of Falcon Watch this is the manner of desperate act that is required of us.", objectives = "Ranger Captain Venn'ren at Falcon Watch wants you to go to the Great Fissure in Hellfire Peninsula and light the Southern Beacon, Western Beacon and Central Beacon. Return to him with the Lit Torch after you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9392] = { id = 9392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogue Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young rogues here on Sunstrider Isle, your trainer is Pathstalker Kariel.  Speak with Kariel and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nKariel - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "I've heard your name whispered from the shadows, {name}.  It's said that you're looking for someone experienced to show you the ropes - someone like me.  I can do that, but it'll cost you a small cut of your take every time I've got something to teach you.  So yes, I will train you in what it means to be a {class}.\n\nBut remember, if you get caught stealing something, this conversation never took place.  Now get out there and show me what you're made of!", objectives = "Speak with Pathstalker Kariel - the Rogue class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9393] = { id = 9393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young hunters here on Sunstrider Isle, your trainer is Ranger Sallina.  Speak with Sallina and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nSallina - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "{name}, are your eyes keen as a hawk's, your motions as fluid as a monkey's, or your speed that of a cheetah?  Mine are, and yours can be too with the proper training.  The way of the {class} is one of mastery over the beasts of the world, an unparalleled precision in marksmanship, and the knowledge of how to survive in situations where others would perish.\n\nIf these are the things that you seek to learn, then I will train you - for a small fee, of course.  Shall we begin?", objectives = "Speak with Ranger Sallina - the Hunter class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9394] = { id = 9394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Wyllithen?", description = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did.  I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about.\n\nWill you find him for me, {class}, and make sure that he's alright?", completion = "Who are you?  You're not one of the magister's apprentices, that's for certain!\n\nSent here to help me clean up this mess, no doubt!", objectives = "Find Groundskeeper Wyllithen on the Duskwither Grounds in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9395] = { id = 9395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Haven", description = "I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party!  Do I look like a party planner?!  Between you and me, that fool and his sycophants are living in denial that we're under attack here!\n\nSome of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas!  {class}, would you please head over to Saltheril's Haven and see if you can shut him up?  It's just down the road to the west.", completion = "Ah, good of Magistrix Dawnstrider to finally respond to my simple requests.  I should take up the matter of her attitude with the regent lord in Silvermoon. She's quite rude!\n\nNothing for you to concern yourself with though. Now that you're here, maybe I'll finally be able to get those party supplies that I've been waiting for?", objectives = "Speak with Lord Saltheril at Saltheril's Haven in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9396] = { id = 9396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic of the Arakkoa", description = "Outland holds many secrets, {name}.  It's only a matter of time before we uncover them all.\n\nThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal'esh, south of here.  Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.", progress = "Have you obtained the scrolls yet, {name}?", completion = "Good work, {name}.  Outland's secrets will not stay hidden from us for very long.\n\nIt's our destiny to become the masters of this world.", objectives = "Bring 4 Haal'eshi Scrolls to Arcanist Calesthris Dawnstar at Falcon Watch in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9397] = { id = 9397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Birds of a Feather", description = "The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri.\n\nI've managed to capture a young male and they appear to be trainable.  The females are much rarer, but if I had one I could attempt to breed them.  She has to be young, though... a hatchling.  An older wild bird wouldn't survive in captivity.\n\nTake this cage and travel south, to the Den of Haal'esh.  Search the nests for eggs that are ready to hatch.  If you bring me back a female hatchling, I'll reward you handsomely.", progress = "You've returned.  Did you bring me the kaliri female?", completion = "You did it!  You caught a female hatchling!\n\nShe's precious.  You have my thanks, {name}.", objectives = "Travel to the Den of Haal'esh in Hellfire Peninsula and search the Kaliri Nests for a Female Kaliri Hatchling. Use the Empty Birdcage to capture it and bring it to Falconer Drenna Riverwind at Falcon Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9398] = { id = 9398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadly Predators", description = "The Broken that live in Outland have endured endless violence.  It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land.\n\nUnfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey.  Go there and thin the rock flayer population, so that our kin might have a chance.", completion = "You've done well, {name}.  It is always unfortunate to have to resort to taking a life, even when it's that of a dangerous beast such as the rock flayer.\n\nYou have my thanks for carrying out this grim task.", objectives = "Scout Vanura at the Temple of Telhamat in Hellfire Peninsula wants you to slay 8 Stonescythe Whelps and 4 Stonescythe Alpha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9399] = { id = 9399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruel Taskmasters", description = "You probably think most Broken are evil, don't you?  In reality many just lack guidance.\n\nBefore I met the Omenai, I too was lost.\n\nOur minds suffered terrible pain from the orcs' demonic magic.  We are easily confused and taken advantage of.\n\nDemons allied with Illidan raid Hellfire daily and capture our kind as slaves.  With the Omenai we now have hope.  Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!", completion = "You did it!  I'm in your debt, {name}.  Look at all the Dreghoods that are showing up.\n\nUnder my guidance they'll learn all about the old ways, you'll see.", objectives = "Slay 4 Illidari Taskmasters at the Ruins of Sha'naar and return to Ikan at the Temple of Telhamat in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9400] = { id = 9400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassin", description = "{name}, we recently uncovered a plot to assassinate our envoy to Falcon Watch.  Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush.\n\nOur scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel.  Go there and slay this assassin.  Show the fel orcs we're not to be trifled with!", completion = "The corpse matches the description of Krun Spinebreaker, Hellfire Citadel's assassin.  As you turn the body over, you notice a stone axe protruding from his back.", objectives = "Nazgrel wants you to travel to the road north of Hellfire Citadel and look for an assassin named Krun Spinebreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9401] = { id = 9401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Weapon", description = "You pull the stone axe out of the body to examine it more closely.  There's something unusual about the craftsmanship of the weapon.\n\nIts origin appears orcish, though the materials aren't like anything you've seen before.  Nazgrel might be interested in seeing the weapon.", progress = "Tell me, is the assassin dead?", completion = "He was killed by this weapon?  It can't be!\n\nHave we... found them?", objectives = "Bring the Heavy Stone Axe to Nazgrel in Thrallmar in Hellfire Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
